"""Encode actual browser frames with original VFR timestamps; never insert/retime frames."""
from pathlib import Path
import json,subprocess,hashlib,statistics,sys
R=Path(__file__).resolve().parents[1];Q=R/'docs/living-korea/quality';j=json.loads((Q/'capture.json').read_text());assert not j['failure']and not j['errors'];delivery=j['frames'];out_of_order=sum(b['timestamp']<=a['timestamp'] for a,b in zip(delivery,delivery[1:]));frames=sorted(delivery,key=lambda f:f['timestamp']);assert len(frames)>300
first=frames[0]['timestamp'];stamps=[f['timestamp']-first for f in frames];assert all(b>a for a,b in zip(stamps,stamps[1:]))
for f in frames:assert hashlib.sha256((R/f['file']).read_bytes()).hexdigest()==f['sha256']
quantized=[round(t*1000)for t in stamps];assert all(b>a for a,b in zip(quantized,quantized[1:]));concat=R/j['rawFramesDirectory']/'frames.ffconcat';lines=['ffconcat version 1.0']
for i,f in enumerate(frames):
 lines += ["file '"+str((R/f['file']).resolve())+"'",'option framerate 1000',f'duration {((quantized[i+1]-quantized[i])/1000)if i+1<len(stamps)else statistics.median(b-a for a,b in zip(stamps,stamps[1:])):.9f}']
concat.write_text('\n'.join(lines)+'\n');mp4=Q/'gameplay-landscape-walkthrough.mp4';cmd=['ffmpeg','-y','-hide_banner','-loglevel','warning','-f','concat','-safe','0','-i',str(concat),'-an','-c:v','libx264','-preset','veryfast','-crf','26','-maxrate','3500k','-bufsize','7000k','-pix_fmt','yuv420p','-fps_mode','vfr','-enc_time_base','1:1000','-video_track_timescale','1000','-movflags','+faststart',str(mp4)]
if '--verify-only' not in sys.argv:
 r=subprocess.run(cmd,capture_output=True,text=True);(Q/'encoder.log').write_text(r.stderr);assert r.returncode==0,r.stderr
probe=['ffprobe','-v','error','-select_streams','v:0','-show_entries','frame=best_effort_timestamp_time','-of','json'];encoded=json.loads(subprocess.check_output([*probe,str(mp4)]));pts=[float(x['best_effort_timestamp_time'])for x in encoded['frames']];assert len(pts)==len(stamps),(len(pts),len(stamps));error=max(abs((a-pts[0])-b)for a,b in zip(pts,stamps));assert error<=.002,error
meta=json.loads(subprocess.check_output(['ffprobe','-v','error','-select_streams','v:0','-count_frames','-show_entries','stream=codec_name,width,height,nb_read_frames,avg_frame_rate:format=duration,size','-of','json',str(mp4)]));duration=float(meta['format']['duration']);native=Q/'native-gameplay-original.webm';n=json.loads(subprocess.check_output(['ffprobe','-v','error','-select_streams','v:0','-count_frames','-show_entries','stream=codec_name,width,height,nb_read_frames:format=duration,size','-of','json',str(native)]))
np=json.loads(subprocess.check_output([*probe,str(native)]));nt=[float(f['best_effort_timestamp_time'])for f in np['frames']];assert len(nt)==int(n['streams'][0]['nb_read_frames']);native_interval=nt[-1]-nt[0];assert native_interval>0
report={'status':'PASS','method':'Actual full-browser CDP JPEG frames to H264 VFR; absolute original timestamps quantized to1ms BEFORE deriving duration differences, preventing accumulated rounding drift; option framerate1000 provides1ms input timebase; explicit encoder/container1/1000; no fps filter, interpolation, duplication, dropped frames or speed changes. Original canvas VP9 independently retained, a different simultaneous capture stream, NOT asserted to have same frame count as CDP.','command':cmd,'deliveryOrderInversions':out_of_order,'timelineOrder':'All original frames sorted by their unchanged CDP capture timestamps, not delivery order. Original delivery list retained in capture.json.','sourceWholeBrowserFrames':len(frames),'encodedWholeBrowserFrames':len(pts),'maxRelativeTimestampErrorSeconds':error,'encodedDurationSeconds':duration,'actualEncodedAverageFPS':len(pts)/duration,'sourceAverageFirstLastFPS':j['sourceWholeBrowserAverageFPS'],'mp4Sha256':hashlib.sha256(mp4.read_bytes()).hexdigest(),'mp4Bytes':mp4.stat().st_size,'nativeCanvas':{'metadata':n,'actualAverageFPS':(len(nt)-1)/native_interval,'firstLastSeconds':native_interval,'durationNote':'Original MediaRecorder WebM has no container duration metadata; decoded first/last presentation timestamps measured directly, average uses (frames-1)/(last-first)','sha256':hashlib.sha256(native.read_bytes()).hexdigest(),'bytes':native.stat().st_size},'rawJPEGRetention':'Ignored execution cache only; every original source frame timestamp/hash is checkpointed in capture.json, both encoded video artifacts are checkpointed.','runtimeDuringCapture':j['runtime'],'visits':len(j['visits']),'errors':j['errors']}
(Q/'video-verification.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items()if k not in ['command','nativeCanvas','runtimeDuringCapture']}));assert mp4.stat().st_size<100_000_000 and native.stat().st_size<100_000_000,'Artifact exceeds GitHub individual-file limit'
